  'settings.reconnect.passwordStored': 'сачувана и никада се не враћа овде',
  'settings.reconnect.passwordHint': 'Сачувана лозинка се никада не шаље назад на ову страницу, зато је поље празно: остави га празно и сачувана остаје. Упиши нову да је замениш. За потпуно уклањање упиши било шта, па поље поново испразни.',

