  'settings.reconnect.importFailed': 'Скрипту није било могуће прочитати: {reason}',

  'settings.reconnect.checkTitle': 'Провера адресе',
  'settings.reconnect.checkUrl': 'URL за проверу IP-а',
  'settings.reconnect.checkUrlHint': 'Дохвата се пре него што се начин изведе и још једном после тога; извођење се рачуна као готово чим се адреса коју исписује промени. Подразумеване вредности нема: менаџер преузимања који сам хостујеш не треба да почне да јавља твоју адресу услузи коју никада ниси изабрао. Оно што исписује мора да буде адреса коју види интернет, јер страница која враћа адресу из твоје сопствене мреже не може да разликује поновно повезивање од извођења које ништа није урадило.',
  'settings.reconnect.checkPresets': 'Познате услуге',
