  'settings.chunks': 'Везе по преузимању (0 = аутоматски)',
  'settings.chunksHint': 'Колико веза отвара једно преузимање када не важи ништа одређеније. Правило или појединачно преузимање може да наведе сопствени број и надјачава овај. Хостер који подноси мање свеједно добија мање: ограничење хостера број може само да спусти, никада да подигне. Уз 0 одлучује апликација. Више од шачице веза код хостера који ограничава по датотеци не доноси ништа и поуздан је начин да налог буде обележен.',
  'task.chunks': 'Везе (0 = глобално подешавање)',
  'task.chunksHint': 'Колико веза отвара баш ово преузимање. Надјачава глобално подешавање и свако правило које га је поставило, али никада хостера: хостер који подноси мање свеједно добија мање. Уз 0 изузетак нестаје и број се поново одлучује другде.',
  'columns.connection': 'Веза',

  'props.title': 'Својства',
  'props.mixed': 'Више вредности',
  'props.mixedHint': 'Ови редови се не слажу, зато је поље празно. Ако га не дирнете, не мења ништа; упишите у њега и сваки изабрани ред добија уписано.',
  'props.name': 'Име',
  'props.nameHint': 'Једно име датотеке, никада путања: све што исписује фасцикле скраћује се на једно име. Завршено преузимање преименује се и на диску, да списак и фасцикла не могу да противрече једно другом. Оно које траје задржава датотеку коју његов бекенд држи отворену и ново име преузима када заврши. Оно које није почело преузима га одмах. Име припада једној датотеци, па се ово поље нуди само за један ред.',
  'props.comment': 'Напомена',
  'props.commentHint': 'Твоја сопствена белешка уз ову везу. Чува се и приказује у листи; ништа у апликацији не ради по њој.',
  'props.priority': 'Приоритет',
  'props.priorityHint': 'Виши иде први. Преслаже оно што још чека; преузимање које већ траје не враћа се у ред.',
  'props.autoExtract': 'Распакуј архиве',
  'props.autoExtractHint': 'Да ли се архива распакује када преузимање заврши. „Наследи“ препушта одлуку страници с подешавањима архива, а то није исто што и искључено. Прекидач се чита у тренутку распакивања, па ако га сад укључиш, распакује се и нешто што је раније завршило.',
