  'strip.label': 'Збирови преузимања',
  'strip.of': 'од',
  'strip.hint': 'Преузети бајтови наспрам дугованих. Завршене, неуспеле и сакупљене везе остају ван збира, као и све чију величину хостер још није навео, јер би нагађање ту дало број са којим нико ништа не може да уради.',
