  'accounts.debrid.hint': 'Debrid услуга је један плаћени налог који одједном откључава много фајлхостера. KnightLoader јој шаље везу и преузима директну везу коју добије назад, пуном брзином и без чекања или captcha. То је препоручени начин, јер је алтернатива засебан премијум налог код сваког појединачног хостера. Неке услуге су доступне само преко уграђеног JDownloader-а, који онда обавља пријаву. Њихови редови то и наводе.',
