  'accounts.routing.priorityHint': 'Која се услуга пита прва када исту везу може да преузме више њих. Превуци ред да га помериш.\n\nГорњи део списка слажеш сам: debrid налоге као што су TorBox и AllDebrid, своје налоге код хостера и торенте. Редослед одлучује само између услуга које заиста могу да преузму везу.\n\nJDownloader, yt-dlp и директно преузимање увек су на крају и не могу да се помере, јер од везе зависи који одговара: веза фајлхостера иде ка JDownloader-у, сајт са видеом ка yt-dlp-у, а обична датотека ка директном преузимању.',
