  'settings.about.cryptoNetworks': 'Мреже',
  'settings.about.cryptoNoTag': 'Ни ознака одредишта ни мемо нису потребни.',
  'common.copy': 'Копирај',
  'common.copied': 'Копирано',
  'settings.about.coffee': 'Ако је KnightLoader заслужио место на твом серверу или рачунару, баци новчић свом витезу: помаже да се покрију трошкови и одржава пројекат у животу. И срце овог витеза куца мало брже. Испод су три пута, узми онај који ти одговара.',
  'settings.about.report': 'Проблеми, жеље или предлози? Отвори проблем на GitHub-у или пошаљи е-пошту.',
