  'settings.scripts.add': 'Додај скрипту',
  'settings.scripts.empty': 'Још нема скрипти',
  'settings.scripts.emptyHint':
    'Скрипта покреће твој сопствени JavaScript када се нешто догоди, на пример када се преузимање заврши, када преузимање не успе или када ред чекања остане без посла. Можеш и сам да је покренеш кад год хоћеш, преко „Пробно покретање“ овде или преко ставке „Покрени скрипту“ у менију десног клика на листи преузимања. Додај једну за почетак.',
  'settings.scripts.loadFailed':
    'Скрипте нису могле да се учитају. Ако овај билд још не садржи механизам за аутоматизацију, ова страница нема шта да прикаже. Покушај поново када га буде садржао.',
