  'settings.access.relay.title': 'Релеј пројекта',
  'settings.access.relay.body': 'Релеј је посредник који све твоје инстанце чини доступним изван кућне мреже, дакле одсвуда. Овај пројекат нуди бесплатно.',
  'settings.access.relay.use': 'Користи релеј пројекта',
  'settings.access.relay.leadProject': 'Ради без подешавања. Све што твоје инстанце једна другој кажу је шифровано, а кључ имаш само ти.',
  'settings.access.relay.address': 'Адреса',
  'settings.access.relay.seesButton': 'Шта види?',
  'settings.access.relay.seesTip': 'Релеј не види: твоје линкове, преузимања, датотеке и приступни токен.\n\nРелеј види: IP адресе твојих инстанци и када нешто пошаљу.\n\nТо се не да сакрити шифровањем. Ако ти смета, подигни сопствени релеј.',
  'settings.access.relay.none': 'Без релеја',
  'settings.access.relay.noneHint': 'Ниједан релеј није активан. У истој мрежи, дакле код куће, инстанце се и даље саме налазе. Преко различитих мрежа не досежу једна другу, па удаљеног приступа нема.',
