  'settings.resolvers.intro': 'Подешавања за yt-dlp позадину, која преузима са медијских и стриминг сајтова које подржава сам yt-dlp. Која услуга уопште обрађује дату везу (yt-dlp, debrid налог или headless JD sidecar) одлучује редослед рутирања на страници Налози. Ова страница подешава шта yt-dlp ради када је веза усмерена ка њему.',
  'settings.resolvers.quality': 'Квалитет',
