  'settings.torrents.pex': 'Размена пирова (PEX)',
  'settings.torrents.pexHint': 'Размењује познате пирове са већ повезанима, како би се рој са мало пирова брже пронашао.',
  'settings.torrents.privateNote': 'Приватни торент аутоматски искључује обе опције чим су му познати метаподаци, без обзира на подешавање овде: одмах код отпремљене .torrent датотеке или чим сопствени метаподаци magnet везе стигну из роја. Већина приватних трекера банује налоге који користе било коју од њих.',
  'settings.torrents.engineNote': 'Циљни однос сидовања и циљно трајање сидовања важе за сваки торент који покрене овај механизам. Порт важи само за први торент покренут од последњег поновног покретања ове инстанце, јер механизам свој торент клијент прави једном и никада га не прави поново. Каснија промена порта се ипак исправно чува и важи од следећег поновног покретања. Ограничење слања се засад само чува и проверава; механизам још не може да га примени на преузимање у току. За обичан торент ни DHT ни PEX испод још не делују: сопствена подразумевана вредност ове инстанце не досеже преузимање у току, па торент сидује са оба укључена, без обзира на подешавање овде. Приватни торент је други случај, описан у напомени ниже. Дугме за мапирање ниже ипак ради: тражи од рутера да проследи број порта унет изнад, без обзира на то да ли неки торент већ слуша на њему.',
