  'onboarding.finish': 'Готово',
  'onboarding.welcome.title': 'Добро дошао у KnightLoader',
  'onboarding.welcome.body': 'KnightLoader је менаџер преузимања који сам хостујеш. Налепи или превуци везу и одговарајућа позадина ће је преузети: уграђени механизам за обичне везе ка датотекама, yt-dlp за медијске странице, debrid услуга за хостере које већ плаћаш или headless JDownloader за све остало. Ова кратка тура показује једино подешавање које вреди проверити пре почетка.',
  'onboarding.welcome.langLabel': 'Језик интерфејса',
  'onboarding.folder.title': 'Где би требало да заврше датотеке?',
  'onboarding.folder.body': 'Ово је фасцикла у коју се уписују завршена преузимања. Упиши путању или је потражи на серверу. Можеш да је промениш кад год хоћеш на страници Опште у подешавањима.',
  'onboarding.accounts.title': 'Премијум хостери, кад год пожелиш',
  'onboarding.accounts.body': 'Ред чекања ради и потпуно без налога. Када пожелиш пуну брзину код хостера или debrid услуге коју већ плаћаш, додај њену пријаву под Налози. Ништа од овога не мора да се подеси сада.',
  'onboarding.accounts.link': 'Отвори Налоге',
  'onboarding.finished.title': 'Спреман си',
  'onboarding.finished.body': 'Тиме се тура завршава. Страница Помоћ унутар Подешавања садржи потпун преглед свега осталог што ова верзија ради, а већина контрола носи сопствено објашњење иза иконице (i).',

