  'settings.rules.action.category': 'Категорија',
  'settings.rules.action.categoryHint': 'Слаже везе које се поклопе у једну од фиока са листе Категорије ниже на овој страници, а она са собом доноси сопствену фасциклу, своје место у реду, свој прекидач за распакивање и своје правило за датотеку која већ постоји. Остављено непромењено, ниједно правило о томе не говори ништа и веза остаје несложена. Ако ово правило наведе и фасциклу за преузимања, побеђује та фасцикла, а фиока и даље даје све остало. Навођење обрисане фиоке одбија се при чувању, јер правило које показује на фиоку која не постоји не ради баш ништа ни на једној вези коју ухвати, и о томе не каже ни реч.',
  'settings.rules.action.categoryNone': 'Још нема категорија. Прво направи једну у листи Категорије ниже на овој страници, иначе би ово правило слагало везе у фиоку која не постоји.',
