  'detail.retriesHint': 'Колико пута је ово преузимање поново покушано после грешке. Чим преузимање заврши, бројач се враћа на нулу, па завршен ред показује нулу и када је требало четири налета. Колико покушаја је остало овде не пише: горња граница зависи од узрока и од хостера, а ова страница не може да је израчуна.',
