  'detail.message': 'Шта је позадина рекла',
  'detail.messageHint': 'Реченица оног што је покушало да ово дохвати, од речи до речи и непреведена. То је тренутна грешка и ништа друго: поновно покретање је брише, а старије се нигде не чувају.',
  'detail.heldBack': 'Задржава га',
  'detail.doing': 'Тренутно ради',
  'detail.filtered': 'Задржано филтером веза',
  'detail.gaveUp': 'Нема више покушаја',
  'detail.gaveUpHint': 'Овде је намерно крај, а не зато што су покушаји потрошени: captcha, пун диск или правило које за овог хостера каже „никада“. Подизање броја покушаја овде не мења ништа. Сама ознака се не уписује у базу података, па после поновног покретања нестаје, иако разлог за њу остаје.',
  'detail.rules': 'Правила која су ово обликовала',
  'detail.rulesHint': 'Правила која су се при припреми окинула на ову везу, редоследом којим су радила. Чувају се по називу: правило које је од тада преименовано више се не проналази, а правило које никада није имало назив чува се по месту које је тада имало. Клик на неко од њих отвара га у уређивачу правила.',
