  'detail.playRemote': 'Овде се пуштају само датотеке са ове инстанце. Друга инстанца своје датотеке предаје у једном комаду и без прескакања, а с тим плејер не може да ради.',
  'detail.playNotLocal': 'Ово преузимање је дохватио JDownloader, па датотека лежи на диску тог процеса, а не на овом.',
  'detail.playNoFile': 'На диску још нема ничега за пуштање.',
