  'notifications.event.captchaWaiting': 'Captcha чека',
  'notifications.event.captchaWaitingHint': 'Captcha прозор се у овој картици отвара у сваком случају. Стоји на „Не приказуј ништа“ јер је тај прозор већ сам по себи порука док гледаш у њега. Постави га на системско обавештење и captcha у позадинској картици те стиже пре него што хостер одбаци сесију.',
  'notifications.event.captchaFailed': 'Captcha није успела',
