  'notifications.systemUnavailable': 'Системска обавештења овде нису доступна: твој прегледач их нуди само преко HTTPS-а или на localhost-у. Све са ове картице се свеједно приказује у апликацији.',
  'notifications.systemBlocked': 'Твој прегледач блокира обавештења за ову адресу. Редови постављени на „Системско обавештење“ приказују се уместо тога у апликацији, док их поново не дозволиш у подешавањима сајта у свом прегледачу.',
  'notifications.systemNotGranted': 'Прегледач није дао дозволу, па овај догађај остаје у апликацији. Изабери поново „Системско обавештење“ да се питање понови.',
