  'failure.botCheck.hint': 'Чекање, спорије преузимање или друга ознака прегледача овде не мењају ништа. Помажу само колачићи из прегледача у коме си стварно пријављен. Извези cookies.txt тог сајта из тог прегледача и налепи је овде: слеће у шифровано складиште акредитива, предаје се yt-dlp-у као датотека коју може да чита само овај сервер, и брише се чим се преузимање заврши.',
  'failure.botCheck.action': 'Сачувај колачиће за овај сајт',
