  'settings.selftest.accounts.advice.error': 'Добављач наводи нешто што не решава ни нов кључ ни чекање, на пример забрану за твоју адресу.',
  'settings.selftest.accounts.readOnlyHint': 'Ова провера не мења ништа у распоређивању. Пријава која овде падне јавља се, а не одлаже се на страну: самопровера при отказаној линији не сме да стави сваки налог на лед за следећих четврт сата.',
